{
  "technical_and_design_decisions": [
    "The library is implemented in Go, consistent with the Hyperledger Fabric codebase and its existing config package.",
    "Reuse the existing fabric-protos generated types (common.Config, common.ConfigUpdate, msp.FabricMSPConfig, etc.) rather than redefining structures.",
    "Follow the established patterns of the existing config package (e.g., UpdateChannelConfiguration, AddOrg) to ensure a consistent API surface.",
    "Anchor peer add/remove operations are implemented by computing a ConfigUpdate via the standard 'headers' + 'config' (desired) + 'write_set' (empty) pattern, leaving signing to a separate workflow.",
    "Certificate validation for U4 uses the standard library crypto/x509 package to parse and inspect the KeyUsage and BasicConstraints CA fields; no additional PKI infrastructure is introduced.",
    "U3 modifies only the revocation_list field of FabricMSPConfig via the standard config update mechanism, avoiding changes to other MSP fields.",
    "Helper functions for U7/U8 return the strongly-typed protos (e.g., config.AnchorPeers, config.Orderer) so callers can mutate them before passing back to update functions.",
    "Documentation examples (U5, U6) are provided as Go example tests (Example* functions in *_test.go files) so they are executable, validated by `go test`, and rendered in GoDoc."
  ],
  "assumptions": [
    "A single experienced Go developer with working knowledge of Hyperledger Fabric performs all work; no onboarding time is included.",
    "The existing config package already exposes primitives such as ConfigUpdateFromConfigBlock, SignConfigUpdate, and an Orderer update function; this work extends them rather than rewriting them.",
    "Test fixtures (sample config blocks, MSP configs, and certificates) can be generated or reused from existing Fabric test data without creating a full Fabric test network.",
    "Code review is performed by the same developer as a self-review and refactor pass before submission; no external reviewer cycles are scheduled.",
    "All efforts are expressed in ideal developer workdays of focused, uninterrupted implementation time.",
    "No CI/CD, release, or governance (Hyperledger Fabric LF process) work is included."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Exploration, design and project setup",
      "activity_description": "Read the existing config package and protos, confirm signatures, sketch the public API surface, set up branch and skeleton files."
    },
    {
      "activity_id": "A2",
      "activity_name": "U1 - Implement add anchor peer",
      "activity_description": "Add a function that takes an existing Config block and an anchor peer (host:port) plus org, and returns a ConfigUpdate that adds it to the channel's anchor peer set."
    },
    {
      "activity_id": "A3",
      "activity_name": "U2 - Implement remove anchor peer",
      "activity_description": "Add a function that takes an existing Config block, an org and an anchor peer, and returns a ConfigUpdate that removes the matching entry from the anchor peer set."
    },
    {
      "activity_id": "A4",
      "activity_name": "U3 - Implement MSP certificate revocation",
      "activity_description": "Add a function that, given a Config block and a certificate identifier (or serial), produces a ConfigUpdate that appends/removes the entry in the FabricMSPConfig revocation_list of the relevant MSP."
    },
    {
      "activity_id": "A5",
      "activity_name": "U4 - Implement add root CA cert with validation",
      "activity_description": "Add a function that validates a candidate CA certificate (reject those missing KeyUsageCertSign or CA=true in BasicConstraints) and returns a ConfigUpdate that appends it to the MSP's tls/intermediate/root cert list as appropriate."
    },
    {
      "activity_id": "A6",
      "activity_name": "U7 - Implement get anchor peers helper",
      "activity_description": "Add a helper that, given a Config block and an org MSP ID, returns the current anchor peer set for that org without manual proto walking."
    },
    {
      "activity_id": "A7",
      "activity_name": "U8 - Implement get orderer configuration helper",
      "activity_description": "Add a helper that returns the current config.Orderer structure from a Config block so callers can mutate and pass it back to UpdateOrdererConfiguration."
    },
    {
      "activity_id": "A8",
      "activity_name": "U5 - GoDoc example for config update",
      "activity_description": "Write an Example* test demonstrating idiomatic usage of the package to build and sign a channel config update with multiple changes."
    },
    {
      "activity_id": "A9",
      "activity_name": "U6 - GoDoc example for channel creation",
      "activity_description": "Write an Example* test demonstrating idiomatic usage of the package to build and sign a new channel creation transaction."
    },
    {
      "activity_id": "A10",
      "activity_name": "Unit tests for new functions",
      "activity_description": "Table-driven unit tests for A2-A7 covering happy paths, missing fields, invalid input and idempotency on well-formed Config blocks."
    },
    {
      "activity_id": "A11",
      "activity_name": "Integration and end-to-end tests",
      "activity_description": "Tests that apply the produced ConfigUpdates against a live config block and verify the resulting read_set/write_set, and update existing example_test.go to cover the new helpers."
    },
    {
      "activity_id": "A12",
      "activity_name": "Self-review, refactor and documentation polish",
      "activity_description": "Refactor duplicated code, ensure godoc comments on all exported identifiers, run gofmt/vet/lint and finalize the change set for submission."
    }
  ],
  "activities_with_effort": [
    {"activity_id": "A1", "most_likely_effort": 1.0},
    {"activity_id": "A2", "most_likely_effort": 1.5},
    {"activity_id": "A3", "most_likely_effort": 1.0},
    {"activity_id": "A4", "most_likely_effort": 2.0},
    {"activity_id": "A5", "most_likely_effort": 2.5},
    {"activity_id": "A6", "most_likely_effort": 0.5},
    {"activity_id": "A7", "most_likely_effort": 1.0},
    {"activity_id": "A8", "most_likely_effort": 1.0},
    {"activity_id": "A9", "most_likely_effort": 1.0},
    {"activity_id": "A10", "most_likely_effort": 2.0},
    {"activity_id": "A11", "most_likely_effort": 1.5},
    {"activity_id": "A12", "most_likely_effort": 1.5}
  ],
  "reported_total": {
    "most_likely_effort": 16.5
  }
}
